const { parse } = require("csv-parse/sync");

// Fetches the published roster CSV and returns an array of row objects.
// Each row looks like: { "Staff ID": "S001", "Staff Name": "Andrea Chua", "Date": "2026-07-01", "Clock In": "08:00", "Clock Out": "17:00" }
async function fetchRosterRows() {
  const url = process.env.ROSTER_SHEET_CSV_URL;

  if (!url) {
    throw new Error("ROSTER_SHEET_CSV_URL is not set in .env");
  }

  const response = await fetch(url);

  if (!response.ok) {
    throw new Error(`Failed to fetch roster sheet: ${response.status} ${response.statusText}`);
  }

  const csvText = await response.text();

  const rows = parse(csvText, {
    columns: true,       // use first row as headers
    skip_empty_lines: true,
    trim: true,
  });

  return rows;
}

module.exports = { fetchRosterRows };
// UC-001: Turns a "clock in" / "clock out" time into a number of hours.
// Times are simple 24-hour strings like "08:00" or "17:30".

function timeStringToMinutes(timeString) {
  const [hours, minutes] = timeString.split(":").map(Number);
  return hours * 60 + minutes;
}

function calculateHours(clockIn, clockOut) {
  let minutesWorked = timeStringToMinutes(clockOut) - timeStringToMinutes(clockIn);

  // Negative means the shift crossed midnight (e.g. 22:00 -> 06:00) â€” add a day.
  if (minutesWorked < 0) {
    minutesWorked += 24 * 60;
  }

  const hoursWorked = minutesWorked / 60;

  // Round to 2 decimal places so totals look clean (e.g. 8.5, not 8.500000001).
  return Math.round(hoursWorked * 100) / 100;
}

module.exports = { calculateHours };
// Shared audit logger (per the design doc's "Audit Logger" component, used
// by all use cases). Records who did what and when, so past actions
// (e.g. sync runs) can be looked up later instead of only ever seeing the
// current state.

const { pool } = require("../config/database");

async function logAction({ entityType, entityId, action, actor, detail }) {
  await pool.query(
    `INSERT INTO audit_log (entity_type, entity_id, action, actor, detail) VALUES ($1, $2, $3, $4, $5)`,
    [entityType, entityId, action, actor, detail ? JSON.stringify(detail) : null]
  );
}

async function getHistory(entityType, entityId, limit = 10) {
  const { rows } = await pool.query(
    `SELECT action, actor, detail, created_at
     FROM audit_log
     WHERE entity_type = $1 AND entity_id = $2
     ORDER BY created_at DESC
     LIMIT $3`,
    [entityType, entityId, limit]
  );
  return rows.map((row) => ({
    action: row.action,
    actor: row.actor,
    detail: row.detail,
    createdAt: row.created_at.toISOString(),
  }));
}

module.exports = { logAction, getHistory };
