// .env lives at the payroll-automation project root, one level above
// backend/ — must load before anything below reads process.env.
require('dotenv').config({ path: require('path').resolve(__dirname, '../../.env') });

const app = require('./app');
const rosterSyncScheduler = require('./jobs/rosterSyncScheduler');
const payPeriodService = require('./services/payPeriodService');

const PORT = Number(process.env.PORT || 5000);

function startServer(port) {
  const server = app.listen(port, () => {
    console.log(`[server] Payroll backend running on http://localhost:${port}`);
  });

  server.on('error', (err) => {
    if (err.code === 'EADDRINUSE') {
      console.error(
        `[server] Port ${port} is already in use. Please free this port or update PORT in .env and restart the backend.`,
      );
      process.exit(1);
    }

    console.error('[server] Failed to start', err.message);
    process.exit(1);
  });
}

async function start() {
  const seedingResult = await payPeriodService.ensurePayPeriodsSeeded();
  if (!seedingResult.ok) {
    console.warn('[server] Continuing startup in degraded mode because the database is unavailable.');
  }

  startServer(PORT);
  rosterSyncScheduler.start();
}

start().catch((err) => {
  console.error('[server] Failed to start — is PostgreSQL running? (docker-compose up)', err.message);
  process.exit(1);
});

