      : backendStatus === 'error'
        ? 'Database disconnected'
        : 'Checking connection...';

  const statusColor =
    backendStatus === 'connected' ? '#16a34a' : backendStatus === 'error' ? '#dc2626' : '#d97706';

  return (
    <div className="page">
      <div className="page-intro">
        <h2>Roster Sync</h2>
