// UC-001: The core roster-sync logic.
// Matches roster rows to staff and saves each one as its own shift-level
// timesheet row (not summed), so UC-002 can later check per-date rules
// like overlapping shifts. Unmatched/invalid rows are flagged and excluded
// from totals instead of corrupting them.

const { pool } = require("../config/database");
const { fetchRosterRows } = require("../adapters/googleSheetsAdapter");
const payPeriodService = require("./payPeriodService");
const auditService = require("./auditService");
const { calculateHours } = require("../utils/hoursCalculator");

// Match a roster row to an active staff record. Staff ID is checked first
// because it's the reliable identifier; name is only a fallback for when
// the ID is missing or wrong, since names can have typos or duplicates.
// If a record exists but is inactive, that's reported separately from a
// truly unknown staff member, since the fix for each is different.
async function findMatchingStaff(rosterRow) {
  const byId = await pool.query(
    `SELECT id, external_ref AS "staffId", full_name AS "fullName", status FROM staff WHERE external_ref = $1`,
    [rosterRow["Staff ID"]]
  );
  const idMatch = byId.rows[0];
  if (idMatch && idMatch.status === "active") return { ...idMatch, matchMethod: "id" };

  const byName = await pool.query(
    `SELECT id, external_ref AS "staffId", full_name AS "fullName", status FROM staff WHERE lower(full_name) = lower($1)`,
    [rosterRow["Staff Name"]]
  );
  const nameMatch = byName.rows[0];
  if (nameMatch && nameMatch.status === "active") return { ...nameMatch, matchMethod: "name" };

  const inactiveMatch = (idMatch && idMatch.status === "inactive") || (nameMatch && nameMatch.status === "inactive");
  if (inactiveMatch) return { inactive: true, fullName: (idMatch || nameMatch).fullName };

  return null;
}

// Runs a full roster sync: read rows -> match -> total hours -> save draft.
// payPeriodId defaults to whichever period covers today, so "Import Now"
// and the automatic scheduler both work without the caller picking one.
async function runRosterSync(payPeriodId, actor = "manual") {
  if (!payPeriodId) {
    const activePeriod = await payPeriodService.getActivePayPeriod();
    payPeriodId = activePeriod.id;
  }

  const previousDraft = await getLastSyncResult(payPeriodId);
  let rosterRows;

  try {
    rosterRows = await fetchRosterRows();
  } catch (err) {
    console.error("[rosterSyncService] Could not read the roster sheet:", err.message);
    await auditService.logAction({
      entityType: "pay_period",
      entityId: payPeriodId,
      action: "roster_sync_failed",
      actor,
      detail: { reason: "unreachable" },
    });
    return {
      success: false,
      error: "ROSTER_SOURCE_UNREACHABLE",
      message: "Google Sheet could not be read; previous draft retained",
      previousDraft,
    };
  }

  if (!rosterRows || rosterRows.length === 0) {
    console.error("[rosterSyncService] The roster sheet had no rows.");
    await auditService.logAction({
      entityType: "pay_period",
      entityId: payPeriodId,
      action: "roster_sync_failed",
      actor,
      detail: { reason: "empty" },
    });
    return {
      success: false,
      error: "ROSTER_SOURCE_EMPTY",
      message: "Google Sheet was empty; previous draft retained",
      previousDraft,
    };
  }

  const matchedShifts = [];
  const unmatchedRows = [];
  const invalidTimeRows = [];

  for (const row of rosterRows) {
    const matchResult = await findMatchingStaff(row);
    const hoursForRow = calculateHours(row["Clock In"], row["Clock Out"]);

    if (Number.isNaN(hoursForRow)) {
      const label = matchResult && !matchResult.inactive ? matchResult.fullName : row["Staff Name"];
      invalidTimeRows.push({
        staffDbId: matchResult && !matchResult.inactive ? matchResult.id : null,
        rosterRawName: `${label} (missing clock-in/out)`,
        date: row["Date"],
      });
      continue;
    }

    if (!matchResult) {
      unmatchedRows.push({ rosterRawName: row["Staff Name"], date: row["Date"], hours: hoursForRow });
      continue;
    }

    if (matchResult.inactive) {
      unmatchedRows.push({ rosterRawName: `${matchResult.fullName} (inactive staff)`, date: row["Date"], hours: hoursForRow });
      continue;
    }

    matchedShifts.push({
      staffDbId: matchResult.id,
      date: row["Date"],
      hours: hoursForRow,
      matchMethod: matchResult.matchMethod,
      clockIn: row["Clock In"],
      clockOut: row["Clock Out"],
    });
  }

  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    // Replace the draft for this period. Rows already frozen by UC-002
    // validation are left alone, so a re-sync can never overwrite a
    // validated snapshot.
    await client.query("DELETE FROM timesheet WHERE pay_period_id = $1 AND is_frozen = false", [payPeriodId]);

    for (const shift of matchedShifts) {
      await client.query(
        `INSERT INTO timesheet (pay_period_id, staff_id, shift_date, total_hours, match_status, match_method, clock_in, clock_out)
         VALUES ($1, $2, $3, $4, 'matched', $5, $6, $7)`,
        [payPeriodId, shift.staffDbId, shift.date, shift.hours, shift.matchMethod, shift.clockIn, shift.clockOut]
      );
    }

    for (const entry of unmatchedRows) {
      await client.query(
        `INSERT INTO timesheet (pay_period_id, staff_id, roster_raw_name, shift_date, total_hours, match_status)
         VALUES ($1, NULL, $2, $3, $4, 'unmatched')`,
        [payPeriodId, entry.rosterRawName, entry.date, entry.hours]
      );
    }

    for (const entry of invalidTimeRows) {
      await client.query(
        `INSERT INTO timesheet (pay_period_id, staff_id, roster_raw_name, shift_date, total_hours, match_status)
         VALUES ($1, $2, $3, $4, 0, 'invalid_time')`,
        [payPeriodId, entry.staffDbId, entry.rosterRawName, entry.date]
      );
    }

    await client.query("COMMIT");
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }

  const result = await getLastSyncResult(payPeriodId);
  await auditService.logAction({
    entityType: "pay_period",
    entityId: payPeriodId,
    action: "roster_synced",
    actor,
    detail: {
      staffSynced: result.staffSynced,
      totalHours: result.totalHours,
      unmatchedCount: result.unmatchedCount,
      invalidTimeCount: result.invalidTimeCount,
    },
  });
  return result;
}

// Returns whatever the last sync produced for a pay period, without
// running a new sync. Used when the page first loads, so it shows the
// latest draft immediately.
async function getLastSyncResult(payPeriodId) {
  if (!payPeriodId) {
    const activePeriod = await payPeriodService.getActivePayPeriod();
    payPeriodId = activePeriod.id;
  }

  const { rows } = await pool.query(
    `SELECT s.external_ref AS staff_ext_ref, s.full_name,
            t.roster_raw_name, to_char(t.shift_date, 'YYYY-MM-DD') AS shift_date,
            t.total_hours, t.match_status, t.match_method, t.clock_in, t.clock_out, t.updated_at
     FROM timesheet t
     LEFT JOIN staff s ON s.id = t.staff_id
     WHERE t.pay_period_id = $1
     ORDER BY t.shift_date`,
    [payPeriodId]
  );

  if (rows.length === 0) {
    return {
      success: false,
      payPeriodId,
      message: 'No sync has been run yet for this pay period. Click "Import Now" to run the first sync.',
    };
  }

  const totalsByStaff = new Map();
  rows
    .filter((row) => row.match_status === "matched")
    .forEach((row) => {
      const existing = totalsByStaff.get(row.staff_ext_ref) || {
        staffId: row.staff_ext_ref,
        fullName: row.full_name,
        totalHours: 0,
        shifts: [],
      };
      existing.totalHours += Number(row.total_hours);
      existing.shifts.push({
        date: row.shift_date,
        hours: Number(row.total_hours),
        matchedBy: row.match_method,
        clockIn: row.clock_in,
        clockOut: row.clock_out,
      });
      totalsByStaff.set(row.staff_ext_ref, existing);
    });

  const draftTimesheets = Array.from(totalsByStaff.values()).map((staffTotal) => ({
    ...staffTotal,
    totalHours: Math.round(staffTotal.totalHours * 100) / 100,
    matchStatus: "matched",
  }));

  const unmatched = rows
    .filter((row) => row.match_status === "unmatched")
    .map((row) => ({
      rosterRawName: row.roster_raw_name,
      date: row.shift_date,
      hours: Number(row.total_hours),
    }));

  const invalidTime = rows
    .filter((row) => row.match_status === "invalid_time")
    .map((row) => ({
      rosterRawName: row.roster_raw_name || row.full_name,
      date: row.shift_date,
    }));

  const totalHours = Math.round(draftTimesheets.reduce((sum, t) => sum + t.totalHours, 0) * 100) / 100;
  const syncedAt = rows.reduce((latest, row) => (row.updated_at > latest ? row.updated_at : latest), rows[0].updated_at);

  return {
    success: true,
    payPeriodId,
    staffSynced: draftTimesheets.length,
    totalHours,
    unmatchedCount: unmatched.length,
    invalidTimeCount: invalidTime.length,
    syncedAt: syncedAt.toISOString(),
    draftTimesheets,
    unmatched,
    invalidTime,
  };
}

// Recent sync events for this pay period (both scheduled and manual), for
// the "Sync History" panel on the frontend.
async function getSyncHistory(payPeriodId, limit = 10) {
  return auditService.getHistory("pay_period", payPeriodId, limit);
}

module.exports = { runRosterSync, getLastSyncResult, getSyncHistory };
import { useState, useEffect } from "react";
import {
  fetchPayPeriods,
  fetchSyncSummary,
  triggerImportNow,
  simulateSheetDown,
  fetchSyncHistory,
} from "../api/roster";
import SyncSummaryCard from "../components/SyncSummaryCard";
import ExceptionList from "../components/ExceptionList";
import SyncHistoryList from "../components/SyncHistoryList";

// UC-001 page: accounting staff can pick a pay period, trigger a manual
// roster sync for it, and see the results â€” sync summary, per-staff shift
// breakdown, unmatched/data-issue entries, and recent sync history.
function RosterSyncPage() {
  const [payPeriods, setPayPeriods] = useState([]);
  const [selectedPayPeriodId, setSelectedPayPeriodId] = useState(null);
  const [summary, setSummary] = useState(null);
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(false);
  const [errorMessage, setErrorMessage] = useState(null);

  function refreshSummaryAndHistory(payPeriodId) {
    fetchSyncSummary(payPeriodId).then(setSummary);
    fetchSyncHistory(payPeriodId).then((res) => setHistory(res.history));
  }

  useEffect(() => {
    fetchPayPeriods().then((periods) => {
      setPayPeriods(periods);
      const defaultPeriod = periods.find((period) => period.isActive) || periods[0];
      if (defaultPeriod) {
        setSelectedPayPeriodId(defaultPeriod.id);
        refreshSummaryAndHistory(defaultPeriod.id);
      }
    });
  }, []);

  function handlePayPeriodChange(event) {
    const payPeriodId = event.target.value;
    setSelectedPayPeriodId(payPeriodId);
    setErrorMessage(null);
    refreshSummaryAndHistory(payPeriodId);
  }

  async function handleImportNow() {
    setLoading(true);
    setErrorMessage(null);

    try {
      const result = await triggerImportNow(selectedPayPeriodId);
      if (!result.success) {
        setErrorMessage(result.message);
        if (result.previousDraft) setSummary(result.previousDraft);
      } else {
        setSummary(result);
      }
      fetchSyncHistory(selectedPayPeriodId).then((res) => setHistory(res.history));
    } catch (err) {
      setErrorMessage(err.message);
    } finally {
      setLoading(false);
    }
  }

  async function handleSimulateFailure() {
    setLoading(true);
    setErrorMessage(null);
    try {
      const result = await simulateSheetDown(selectedPayPeriodId);
      setErrorMessage(result.message);
      if (result.previousDraft) setSummary(result.previousDraft);
    } finally {
      setLoading(false);
    }
  }

  return (
    <div>
      <h1>UC-001: Roster Sync</h1>

      <div>
        <label>Pay Period: </label>
        <select value={selectedPayPeriodId || ""} onChange={handlePayPeriodChange}>
          {payPeriods.map((period) => (
            <option key={period.id} value={period.id}>
              {period.startDate} to {period.endDate} {period.isActive ? "(active)" : ""}
            </option>
          ))}
        </select>
      </div>

      <button onClick={handleImportNow} disabled={loading}>
        {loading ? "Syncing..." : "Import Now"}
      </button>
      <button onClick={handleSimulateFailure} disabled={loading}>
        Simulate Sheet Down (demo)
      </button>

      {errorMessage && <p style={{ color: "red" }}>{errorMessage}</p>}

      <SyncSummaryCard summary={summary} />
      <ExceptionList unmatched={summary?.unmatched} invalidTime={summary?.invalidTime} />
      <SyncHistoryList history={history} />
    </div>
  );
}

export default RosterSyncPage;
// UC-001: API wrapper functions for roster sync, built on top of the
// shared apiGet/apiPost helpers in api/client.js.

import { apiGet, apiPost } from "./client";

function fetchPayPeriods() {
  return apiGet("/api/pay-periods");
}

function fetchSyncSummary(payPeriodId) {
  return apiGet(`/api/roster/sync/summary?payPeriodId=${payPeriodId}`);
}

function fetchSyncHistory(payPeriodId) {
  return apiGet(`/api/roster/sync/history?payPeriodId=${payPeriodId}`);
}

function triggerImportNow(payPeriodId) {
  return apiPost("/api/roster/sync", { payPeriodId });
}

function simulateSheetDown(payPeriodId) {
  return apiPost("/api/roster/sync", { payPeriodId, simulateFailure: true });
}

export { fetchPayPeriods, fetchSyncSummary, fetchSyncHistory, triggerImportNow, simulateSheetDown };
// UC-001: Handles the HTTP requests for roster sync and passes the work
// along to rosterSyncService, then sends back a JSON response.

const rosterSyncService = require("../services/rosterSyncService");

// POST /api/roster/sync â€” "Import Now" button
async function importNow(req, res, next) {
  try {
    const { payPeriodId, simulateFailure } = req.body;

    if (simulateFailure) {
      // Demo-only path: lets accounting staff show alt flow 1b (sheet
      // unreachable) live without actually editing .env mid-demo.
      const previousDraft = await rosterSyncService.getLastSyncResult(payPeriodId);
      return res.status(424).json({
        success: false,
        error: "ROSTER_SOURCE_UNREACHABLE",
        message: "Simulated failure for demo purposes; previous draft retained",
        previousDraft,
      });
    }

    const result = await rosterSyncService.runRosterSync(payPeriodId, "manual");

    if (!result.success) {
      // 424 = "the thing we depend on (the Google Sheet) failed"
      return res.status(424).json(result);
    }

    res.status(200).json(result);
  } catch (err) {
    next(err);
  }
}

// GET /api/roster/sync/summary â€” shows the latest sync result on page load
async function getSyncSummary(req, res, next) {
  try {
    const result = await rosterSyncService.getLastSyncResult(req.query.payPeriodId);
    res.status(200).json(result);
  } catch (err) {
    next(err);
  }
}

// GET /api/roster/sync/history â€” recent sync events (manual + scheduled) for this period
async function getSyncHistory(req, res, next) {
  try {
    const history = await rosterSyncService.getSyncHistory(req.query.payPeriodId);
    res.status(200).json({ history });
  } catch (err) {
    next(err);
  }
}

module.exports = { importNow, getSyncSummary, getSyncHistory };
const { parse } = require("csv-parse/sync");

// Fetches the published roster CSV and returns an array of row objects.
// Each row looks like: { "Staff ID": "S001", "Staff Name": "Andrea Chua", "Date": "2026-07-01", "Clock In": "08:00", "Clock Out": "17:00" }
async function fetchRosterRows() {
  const url = process.env.ROSTER_SHEET_CSV_URL;

  if (!url) {
    throw new Error("ROSTER_SHEET_CSV_URL is not set in .env");
  }

  const response = await fetch(url);

  if (!response.ok) {
    throw new Error(`Failed to fetch roster sheet: ${response.status} ${response.statusText}`);
  }

  const csvText = await response.text();

  const rows = parse(csvText, {
    columns: true,       // use first row as headers
    skip_empty_lines: true,
    trim: true,
  });

  return rows;
}

module.exports = { fetchRosterRows };
// UC-001: Turns a "clock in" / "clock out" time into a number of hours.
// Times are simple 24-hour strings like "08:00" or "17:30".

function timeStringToMinutes(timeString) {
  const [hours, minutes] = timeString.split(":").map(Number);
  return hours * 60 + minutes;
}

function calculateHours(clockIn, clockOut) {
  let minutesWorked = timeStringToMinutes(clockOut) - timeStringToMinutes(clockIn);

  // Negative means the shift crossed midnight (e.g. 22:00 -> 06:00) â€” add a day.
  if (minutesWorked < 0) {
    minutesWorked += 24 * 60;
  }

  const hoursWorked = minutesWorked / 60;

  // Round to 2 decimal places so totals look clean (e.g. 8.5, not 8.500000001).
  return Math.round(hoursWorked * 100) / 100;
}

module.exports = { calculateHours };
const express = require("express");
const cors = require("cors");
const routes = require("./routes/index");
const requestLogger = require("./middleware/requestLogger");
const errorHandler = require("./middleware/errorHandler");

const app = express();

app.use(cors());
app.use(express.json());
app.use(requestLogger);

const { pool } = require("./config/database");

app.get("/health", async (req, res) => {
  try {
    await pool.query("SELECT 1");
    res.json({ status: "ok", database: "connected" });
  } catch (err) {
    res.status(500).json({ status: "error", database: "disconnected", message: err.message });
  }
});

app.use("/api", routes);

app.use(errorHandler);

module.exports = app;

