  align-items: center;
  gap: 0.6rem;
  margin-bottom: 1rem;
}

.field-row label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--ink-secondary);
}

.field-row select {
  font-family: inherit;
  font-size: 0.9rem;
  padding: 0.5rem 0.75rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--ink-primary);
}

/* Buttons */

.button-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1.5rem;
}

button {
  font-family: inherit;
  padding: 0.65rem 1.15rem;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease, transform 0.05s ease;
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
}

button:active:not(:disabled) {
  transform: translateY(1px);
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

button.primary {
  background: var(--accent);
  color: #ffffff;
}

button.primary:hover:not(:disabled) {
  background: var(--accent-hover);
}

button.secondary {
  background: transparent;
  color: var(--ink-secondary);
  border-color: var(--border);
}

button.secondary:hover:not(:disabled) {
  background: rgba(11, 11, 11, 0.04);
  border-color: var(--ink-muted);
}

.button-row-caption {
  margin-top: 0.5rem;
  font-size: 0.82rem;
}

.spinner {
  width: 13px;
  height: 13px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.4);
  border-top-color: #ffffff;
  animation: spin 0.7s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

/* Banners */

.banner {
  display: flex;
  align-items: flex-start;
  gap: 0.6rem;
  padding: 0.8rem 1rem;
  border-radius: var(--radius-sm);
  margin-bottom: 1.5rem;
  font-size: 0.88rem;
  line-height: 1.45;
}

.banner-icon {
  flex-shrink: 0;
  margin-top: 0.1rem;
}

.error-banner {
  background: var(--critical-wash);
  color: #8a2a2a;
  border: 1px solid rgba(208, 59, 59, 0.25);
}

.info-banner {
  background: #eff6ff;
  color: #1d4ed8;
  border: 1px solid rgba(59, 130, 246, 0.25);
}

/* Stat tiles */

.stat-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.85rem;
  margin-bottom: 1.5rem;
}

.stat-tile {
  background: var(--surface);
  border: 1px solid var(--gridline);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-card);
  padding: 0.95rem 1rem;
}

.stat-tile .stat-label {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--ink-muted);
  margin: 0 0 0.35rem;
}

.stat-tile .stat-value {
  font-size: 1.6rem;
  font-weight: 700;
  line-height: 1.1;
  font-variant-numeric: proportional-nums;
}

.stat-tile .stat-value.stat-warning {
  color: var(--warning);
}

.stat-tile .stat-value.stat-value-time {
  font-size: 0.92rem;
  font-weight: 600;
  line-height: 1.3;
}

.stat-tile .stat-sub {
  margin: 0.3rem 0 0;
  font-size: 0.78rem;
  color: var(--ink-muted);
}

.empty-state {
  background: var(--surface);
  border: 1px dashed var(--gridline);
  border-radius: var(--radius-md);
  padding: 1.5rem;
  text-align: center;
  color: var(--ink-secondary);
  font-size: 0.9rem;
  margin-bottom: 1.5rem;
}

/* Cards */

.card {
  background: var(--surface);
  border: 1px solid var(--gridline);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 1.3rem 1.4rem;
  margin-bottom: 1.5rem;
}

.card-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.9rem;
}

.card h2 {
  font-size: 1rem;
  margin: 0;
}

.card-count {
  font-size: 0.78rem;
  color: var(--ink-muted);
  font-weight: 600;
}

/* Table */

.table-scroll {
  overflow-x: auto;
  margin: -0.2rem -0.1rem;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
}

th,
td {
  text-align: left;
  padding: 0.55rem 0.6rem;
  border-bottom: 1px solid var(--gridline);
  white-space: nowrap;
}

th {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: var(--ink-muted);
}

td.numeric,
th.numeric {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

tbody tr:hover {
  background: rgba(11, 11, 11, 0.025);
}

tbody tr:last-child td {
  border-bottom: none;
}

/* Badges */

.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  font-size: 0.72rem;
  font-weight: 700;
  padding: 0.2rem 0.55rem;
  border-radius: 999px;
  letter-spacing: 0.01em;
}

.badge-good {
  background: var(--good-wash);
  color: #0a7a0a;
}

.badge-warning {
  background: var(--warning-wash);
  color: var(--warning);
}

.badge-critical {
  background: var(--critical-wash);
  color: var(--critical);
}

.badge-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
  flex-shrink: 0;
}

/* Exception list */

.exception-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.exception-item {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.6rem 0.7rem;
  border-radius: var(--radius-sm);
  background: var(--warning-wash);
  font-size: 0.87rem;
}

.exception-item .exception-name {
  font-weight: 600;
}

.exception-item .exception-meta {
  color: var(--ink-secondary);
  margin-left: auto;
  font-size: 0.82rem;
  white-space: nowrap;
}

.exception-item-critical {
  background: var(--critical-wash);
}

/* Expandable shift breakdown rows */

.row-expandable {
  cursor: pointer;
}

.expand-toggle {
  color: var(--accent);
  font-weight: 600;
}

.row-breakdown td {
  background: var(--page-plane);
  padding: 0.75rem 1rem;
}

.breakdown-table {
  font-size: 0.82rem;
}

.breakdown-table th,
.breakdown-table td {
  padding: 0.35rem 0.5rem;
}

/* Sync history */

.history-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.history-item {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  padding: 0.6rem 0.7rem;
  border-radius: var(--radius-sm);
  background: var(--page-plane);
  font-size: 0.87rem;
}

.history-detail {
  color: var(--ink-secondary);
}

.history-time {
  margin-left: auto;
  color: var(--ink-muted);
  font-size: 0.82rem;
  white-space: nowrap;
}

@media (max-width: 640px) {
  .stat-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .card-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.3rem;
  }

  .exception-item {
    flex-wrap: wrap;
  }

  .exception-item .exception-meta {
    margin-left: 0;
  }
}
